public class Main {
  static int modify(int[] arr, int idx) {
    arr[idx] = arr[idx] * 2;
    return arr[idx];
  }

  public static void main(String[] args) {
    int[] numbers = {1, 2, 3, 4, 5};
    int sum = 0;

    for (int i = 0; i < numbers.length; i++) {
      if (i % 2 == 0) {
        sum += modify(numbers, i);
      } else {
        sum += numbers[i];
      }
    }

    for (int i = 0; i < numbers.length; i++) {
      System.out.print(numbers[i] + " ");
    }
    System.out.println();
    System.out.println("sum = " + sum);
  }
}

#include <stdio.h>

void swap(int *a, int *b) {
  int temp = *a;
  *a = *b;
  *b = temp;
}

int calc(int *arr, int size) {
  int result = 0;
  for (int i = 0; i < size; i++) {
    result += arr[i];
    if (i > 0) {
      arr[i] = arr[i] + arr[i - 1];
    }
  }
  return result;
}

int main(void) {
  int nums[5] = {10, 20, 30, 40, 50};

  swap(&nums[0], &nums[4]);

  int total = calc(nums, 5);

  for (int i = 0; i < 5; i++) {
    printf("%d ", nums[i]);
  }
  printf("\n");
  printf("total = %d\n", total);

  return 0;
}

